package com.careernav.controller;
import com.careernav.common.ApiResponse;import com.careernav.config.AppProperties;import com.careernav.domain.ApiModels.*;import com.careernav.service.AgentOrchestrator;import com.careernav.service.LangGraphInterviewClient;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/agent")
public class AgentController {private final AgentOrchestrator orchestrator;private final AppProperties properties;private final LangGraphInterviewClient langGraphClient;public AgentController(AgentOrchestrator orchestrator,AppProperties properties,LangGraphInterviewClient langGraphClient){this.orchestrator=orchestrator;this.properties=properties;this.langGraphClient=langGraphClient;}@PostMapping("/run")public ApiResponse<AgentRunResult> run(@Valid @RequestBody AgentRunRequest request){return ApiResponse.ok("单智能体工具链执行完成",orchestrator.run(request));}@GetMapping("/status")public ApiResponse<Map<String,Object>> status(){boolean online=properties.getAgent().getApiKey()!=null&&!properties.getAgent().getApiKey().isBlank();Map<String,Object> status=new LinkedHashMap<>();status.put("mode",online?"LANGCHAIN4J_ONLINE":"LANGCHAIN4J_LOCAL");status.put("model",online?properties.getAgent().getModel():"local-rule-reasoner");status.put("mcpEnabled",properties.getMcp().isEnabled());status.put("mcpEndpoint",properties.getMcp().getEndpoint());status.put("tools",List.of("resume.profile","job.match","interview.start","resume.diagnose","learning.generate"));status.put("langgraph",langGraphClient.configuration());return ApiResponse.ok(status);}}
